PEGTransformerFactory::FinalizeCreateViewStmtTrampoline(PEGTransformer &transformer,
                                                        GeneratedTransformProcess &process) {
	optional<bool> create_secure {};
	if (process.child_results[0]) {
		create_secure = process.TakeResult<bool>(0);
	}
	optional<bool> create_recursive {};
	if (process.child_results[1]) {
		create_recursive = process.TakeResult<bool>(1);
	}
	optional<bool> if_not_exists {};
	if (process.child_results[2]) {
		if_not_exists = process.TakeResult<bool>(2);
	}
	auto qualified_name = process.TakeResult<QualifiedName>(3);
	optional<vector<string>> insert_column_list {};
	if (process.child_results[4]) {
		insert_column_list = process.TakeResult<vector<string>>(4);
	}
	optional<case_insensitive_map_t<unique_ptr<ParsedExpression>>> with_list {};
	if (process.child_results[5]) {
		with_list = process.TakeResult<case_insensitive_map_t<unique_ptr<ParsedExpression>>>(5);
	}
	auto select_statement_internal = process.TakeResult<unique_ptr<SelectStatement>>(6);
	auto result =
	    TransformCreateViewStmt(transformer, create_secure, create_recursive, if_not_exists, qualified_name,
	                            insert_column_list, std::move(with_list), std::move(select_statement_internal));
	return make_uniq<TypedTransformResult<unique_ptr<CreateStatement>>>(std::move(result));
}

