void PEGTransformerFactory::InitializeStarExpressionTrampoline(PEGTransformer &transformer,
                                                               GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	process.ReserveChildSlots(4);
	auto &rename_list_opt = list_pr.GetChild(4).Cast<OptionalParseResult>();
	if (rename_list_opt.HasResult()) {
		process.PushChild({transformer.GetRule("RenameList"), rename_list_opt.GetResult()}, 3);
	}
	auto &replace_list_opt = list_pr.GetChild(3).Cast<OptionalParseResult>();
	if (replace_list_opt.HasResult()) {
		process.PushChild({transformer.GetRule("ReplaceList"), replace_list_opt.GetResult()}, 2);
	}
	auto &exclude_list_opt = list_pr.GetChild(2).Cast<OptionalParseResult>();
	if (exclude_list_opt.HasResult()) {
		process.PushChild({transformer.GetRule("ExcludeList"), exclude_list_opt.GetResult()}, 1);
	}
	auto &star_qualifier_list_opt = list_pr.GetChild(0).Cast<OptionalParseResult>();
	if (star_qualifier_list_opt.HasResult()) {
		process.PushChild({transformer.GetRule("StarQualifierList"), star_qualifier_list_opt.GetResult()}, 0);
	}
}

unique_ptr<TransformResultValue>
PEGTransformerFactory::FinalizeStarExpressionTrampoline(PEGTransformer &transformer,
                                                        GeneratedTransformProcess &process) {
	optional<vector<string>> star_qualifier_list {};
	if (process.child_results[0]) {
		star_qualifier_list = process.TakeResult<vector<string>>(0);
	}
	optional<qualified_column_set_t> exclude_list {};
	if (process.child_results[1]) {
		exclude_list = process.TakeResult<qualified_column_set_t>(1);
	}
	optional<case_insensitive_map_t<unique_ptr<ParsedExpression>>> replace_list {};
	if (process.child_results[2]) {
		replace_list = process.TakeResult<case_insensitive_map_t<unique_ptr<ParsedExpression>>>(2);
	}
	optional<qualified_column_map_t<string>> rename_list {};
	if (process.child_results[3]) {
		rename_list = process.TakeResult<qualified_column_map_t<string>>(3);
	}
	auto result =
	    TransformStarExpression(transformer, star_qualifier_list, exclude_list, std::move(replace_list), rename_list);
	return make_uniq<TypedTransformResult<unique_ptr<ParsedExpression>>>(std::move(result));
}

