void PEGTransformerFactory::InitializeCatalogReservedSchemaTableTrampoline(PEGTransformer &transformer,
                                                                           GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto &repeat_pr = list_pr.GetChild(1).Cast<RepeatParseResult>();
	auto repeat_children = repeat_pr.GetChildren();
	auto dynamic_child_count = repeat_children.size();
	process.ReserveChildSlots(2 + dynamic_child_count - 1);
	for (idx_t i = repeat_children.size(); i > 0; i--) {
		auto child_idx = i - 1;
		process.PushChild({transformer.GetRule("ReservedSchemaQualification"), repeat_children[child_idx].get()},
		                  1 + child_idx);
	}
	process.PushChild({transformer.GetRule("CatalogQualification"), list_pr.GetChild(0)}, 0);
}

unique_ptr<TransformResultValue>
PEGTransformerFactory::FinalizeCatalogReservedSchemaTableTrampoline(PEGTransformer &transformer,
                                                                    GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto &dynamic_repeat_pr = list_pr.GetChild(1).Cast<RepeatParseResult>();
	auto dynamic_repeat_children = dynamic_repeat_pr.GetChildren();
	auto dynamic_child_count = dynamic_repeat_children.size();
	auto catalog_qualification = process.TakeResult<Identifier>(0);
	vector<Identifier> reserved_schema_qualification;
	for (idx_t i = 1; i < 1 + dynamic_child_count; i++) {
		reserved_schema_qualification.push_back(process.TakeResult<Identifier>(i));
	}
	auto reserved_table_name = list_pr.GetChild(2).Cast<IdentifierParseResult>().identifier;
	auto result = TransformCatalogReservedSchemaTable(transformer, catalog_qualification, reserved_schema_qualification,
	                                                  reserved_table_name);
	return make_uniq<TypedTransformResult<unique_ptr<BaseTableRef>>>(std::move(result));
}

